// ---------------------------------------------------------------------------
// MOD: Loop Size auf dem Gain-Knopf im EQ-Mode, mit echtem Soft Takeover
// Der Gain-Knopf laeuft wie bisher durch "softtakeover1". Im EQ-Mode schreibt
// dessen Ausgang nicht mehr auf den Channel-Gain, sondern auf eine
// stufenlose Hilfsgroesse "loop_size_knob" (0..1). Diese wird auf die
// 11 Loop-Groessen (1/32 .. 32) abgebildet. Aendert sich die Loop Size
// anderweitig (Maus, Tasten, Track-Load), wird die Hilfsgroesse nachgefuehrt,
// damit Soft Takeover den Knopf wieder "abholt".
// Zurueck zum Original-Verhalten: gainKnobIsLoopSize auf false setzen.
// ---------------------------------------------------------------------------
readonly property bool gainKnobIsLoopSize: true
readonly property int  loopSizeMaxIndex: 10   // 0 = 1/32 ... 10 = 32 (siehe Defines/LoopSize.qml)
property bool loopSizeKnobReady: false

MappingPropertyDescriptor { path: module.propertiesPath + ".gain_knob_is_loop_size"; type: MappingPropertyDescriptor.Boolean; value: module.gainKnobIsLoopSize }

AppProperty
{
  id: loopSizeProp
  path: "app.traktor.decks." + module.deckIdx + ".loop.size"
  onValueChanged: module.syncLoopSizeKnobFromDeck()
}

MappingPropertyDescriptor
{
  id: loopSizeKnobProp
  path: module.propertiesPath + ".loop_size_knob"
  type: MappingPropertyDescriptor.Float
  value: 0.7
  min: 0.0
  max: 1.0
  onValueChanged: module.applyLoopSizeKnobToDeck()
}

function loopSizeKnobToIndex(knobValue)
{
  var idx = Math.round(knobValue * module.loopSizeMaxIndex);
  return Math.max(0, Math.min(module.loopSizeMaxIndex, idx));
}

// Knopf (nach Soft Takeover) -> Loop Size
function applyLoopSizeKnobToDeck()
{
  if (!module.gainKnobIsLoopSize || module.deckIdx < 1)
    return;

  // Noch nie die Loop Size des Decks gelesen? Erst synchronisieren, nichts schreiben.
  if (!module.loopSizeKnobReady)
  {
    module.syncLoopSizeKnobFromDeck();
    return;
  }

  var current = loopSizeProp.value;
  if (typeof current !== "number")
    return;

  var idx = module.loopSizeKnobToIndex(loopSizeKnobProp.value);
  if (idx != current)
    loopSizeProp.value = idx;
}

// Loop Size (von woanders geaendert) -> Hilfsgroesse, damit Soft Takeover greift
// Erst wenn die Loop Size des Decks einmal gelesen wurde, darf der Knopf sie
// veraendern (verhindert ein Ueberschreiben beim Start von Traktor).
function syncLoopSizeKnobFromDeck()
{
  var current = loopSizeProp.value;
  if (typeof current !== "number")
    return;

  if (module.loopSizeKnobToIndex(loopSizeKnobProp.value) != current)
    loopSizeKnobProp.value = current / module.loopSizeMaxIndex;

  module.loopSizeKnobReady = true;
}

// Hinweis: kein "Component.onCompleted" - das gibt es in Traktors CSI-Dateien
// nicht (ohne QtQml-Import) und verhindert sonst das Laden des Controllers.
onDeckIdxChanged: module.syncLoopSizeKnobFromDeck()
// ------------------------------------------------------------- Ende MOD ----

