// ---------------------------------------------------------------------------
// MOD: Mit gedrueckter Shift-Taste leuchten die Tasten mit Shift-Belegung:
//   Loop-Taste           gruen  (hell = Loop laeuft, gedimmt = kein Loop)
//   Only-Browser-Taste   weiss  (hell = Only Browser an)
//   Channel-FX-On-Taste  weiss  (Seek / Track-Anfang aus dem Layout)
//   Tasten ohne Shift-Belegung sind dann aus.
// ---------------------------------------------------------------------------
property int browserButton: 0   // 0 = keine, 1 = EQ-Mode-Taste, 2 = Stems-Mode-Taste
readonly property int eqShiftRole:    module.loopButton == 1 ? 1 : (module.browserButton == 1 ? 2 : 0)
readonly property int stemsShiftRole: module.loopButton == 2 ? 1 : (module.browserButton == 2 ? 2 : 0)

AppProperty { id: browserFullScreenProp; path: "app.traktor.browser.full_screen" }

function shiftLedColor(role)
{
  if (role == 1) return Color.Green;
  if (role == 2) return Color.White;   // Only Browser
  return Color.White;
}

function shiftLedBrightness(role)
{
  if (role == 1) return inActiveLoopProp.value === true ? 1.0 : 0.5;
  if (role == 2) return browserFullScreenProp.value === true ? 1.0 : 0.5;
  return 0.0;
}

WiresGroup
{
  enabled: module.shift && module.deckIdx >= 1

  Wire { from: "%surface%.eq_mode";       to: ButtonScriptAdapter { color: module.shiftLedColor(module.eqShiftRole);    brightness: module.shiftLedBrightness(module.eqShiftRole) } }
  Wire { from: "%surface%.stems_mode";    to: ButtonScriptAdapter { color: module.shiftLedColor(module.stemsShiftRole); brightness: module.shiftLedBrightness(module.stemsShiftRole) } }
  Wire { from: "%surface%.channel_fx.on"; to: ButtonScriptAdapter { color: Color.White; brightness: 1.0 } }
}
// ------------------------------------------------------------- Ende MOD ----

// ---------------------------------------------------------------------------
// MOD: Im Stem-Mode mit gedrueckter Shift-Taste stellt der Gain-Knopf die
// Loop Size ein (ohne Shift: Drums). Soft Takeover wie ueberall.
// ---------------------------------------------------------------------------
readonly property bool shiftLoopInStems: module.gainKnobIsLoopSize && module.shift
function stemsModeOfDeck(idx)
{
  switch (idx)
  {
    case 1: return module.channel_mode_1;
    case 2: return module.channel_mode_2;
    case 3: return module.channel_mode_3;
    case 4: return module.channel_mode_4;
  }
  return false;
}
// Fuer das Display: zeigt der Gain-Knopf gerade die Loop Size?
MappingPropertyDescriptor { path: module.propertiesPath + ".knob1_is_loop"; type: MappingPropertyDescriptor.Boolean; value: module.gainKnobIsLoopSize && (!module.stemsModeOfDeck(module.deckIdx) || module.shift) }
