{
  if (!screen.trackLoaded || typeof elapsedTimeProp.value !== "number")
    return "";
  var rest = Math.max(0, Math.floor(trackLengthProp.value - elapsedTimeProp.value));
  var min = Math.floor(rest / 60);
  var sec = rest % 60;
  return "-" + min + ":" + (sec < 10 ? "0" : "") + sec;
}

function bpmText()
{
  if (!screen.trackLoaded || typeof bpmProp.value !== "number" || bpmProp.value <= 0)
    return "";
  return bpmProp.value.toFixed(1);
